<?php
namespace App\Jobs;use App\Models\{BiometricConsent,BiometricDeletionRequest,FaceCollection,IndexedFace,ProviderDeletionOperation};use App\Services\Face\FaceRecognitionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Support\Str;use Throwable;
class ExecuteBiometricDeletion implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=4;public function __construct(public int$requestId){$this->onQueue('maintenance');}public function handle(FaceRecognitionManager$m):void{$r=BiometricDeletionRequest::findOrFail($this->requestId);if($r->state==='completed')return;$r->increment('attempts');$r->update(['state'=>'processing','processing_at'=>now()]);try{BiometricConsent::with('subjects')->where('user_id',$r->user_id)->when($r->group_id,fn($q)=>$q->where('group_id',$r->group_id))->each(function($c)use($m){foreach($c->subjects as$s)$m->deleteSelfie($s);$c->update(['state'=>'deleted']);});$r->update(['state'=>'completed','completed_at'=>now(),'error'=>null]);}catch(Throwable$e){$r->update(['state'=>'failed','error'=>'Biometric deletion failed.']);throw$e;}}}
